<?php
$pdo=db();$attendanceDate=(string)($_GET['date']??date('Y-m-d'));if(!valid_school_date($attendanceDate))$attendanceDate=date('Y-m-d');$classId=filter_var($_GET['class_id']??null,FILTER_VALIDATE_INT);$canRecord=in_array($user['role'],['Administrator','Head','Teacher','Clerk'],true);
$classSql="SELECT c.id,c.form_level,c.stream,c.academic_year,u.full_name AS class_teacher FROM class_groups c LEFT JOIN users u ON u.id=c.class_teacher_id WHERE c.academic_year=YEAR(CURDATE())";$classParams=[];
if($user['role']==='Teacher'){$classSql.=' AND c.class_teacher_id=:teacher_id';$classParams['teacher_id']=$user['id'];}
$classSql.=' ORDER BY c.form_level,c.stream';$classStmt=$pdo->prepare($classSql);$classStmt->execute($classParams);$attendanceClasses=$classStmt->fetchAll();
if(!$classId&&$attendanceClasses)$classId=(int)$attendanceClasses[0]['id'];
$selectedClass=null;foreach($attendanceClasses as $c)if((int)$c['id']===$classId){$selectedClass=$c;break;}
$roster=[];$totals=['Present'=>0,'Absent'=>0,'Late'=>0,'Excused'=>0];
if($selectedClass){
  $stmt=$pdo->prepare("SELECT DISTINCT s.id,s.admission_no,s.first_name,s.last_name,s.sex,a.status,a.note FROM students s JOIN student_enrolments e ON e.student_id=s.id LEFT JOIN attendance a ON a.student_id=s.id AND a.attendance_date=:attendance_date WHERE e.academic_year=:year AND e.form_level=:form AND COALESCE(e.stream,'')=:stream AND e.start_date<=:enrol_start AND (e.end_date IS NULL OR e.end_date>=:enrol_end) ORDER BY s.last_name,s.first_name");
  $stmt->execute(['attendance_date'=>$attendanceDate,'year'=>$selectedClass['academic_year'],'form'=>$selectedClass['form_level'],'stream'=>$selectedClass['stream'],'enrol_start'=>$attendanceDate,'enrol_end'=>$attendanceDate]);$roster=$stmt->fetchAll();
  foreach($roster as $row)if(isset($totals[$row['status']]))$totals[$row['status']]++;
}
$recorded=array_sum($totals);$unmarked=count($roster)-$recorded;
?>
<div class="page-heading"><div><div class="eyebrow">DAILY REGISTER</div><h1>Attendance</h1><p class="subheading">Record presence, lateness and absence by class group.</p></div></div>
<form class="attendance-filter panel" method="get" action="/"><input type="hidden" name="page" value="attendance"><label>Class group<select name="class_id" required><?php if(!$attendanceClasses): ?><option value="">No class groups for this year</option><?php endif; ?><?php foreach($attendanceClasses as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$c['id']===$classId?'selected':'' ?>>Form <?= (int)$c['form_level'] ?><?= h($c['stream']) ?> · <?= (int)$c['academic_year'] ?></option><?php endforeach; ?></select></label><label>Register date<input type="date" name="date" value="<?= h($attendanceDate) ?>" max="<?= date('Y-m-d') ?>" required></label><button class="outline-button">Open register</button><?php if($selectedClass&&$canRecord): ?><button class="primary-button" type="button" id="markAllPresent">Mark all present</button><?php endif; ?></form>
<?php if(!$attendanceClasses): ?><section class="panel empty-state"><span class="empty-icon">◷</span><h2>No classes are assigned for <?= date('Y') ?></h2><p>Create this year’s form groups and assign class teachers in Academics before taking a register.</p><a class="primary-button" href="?page=academics&tab=classes">Set up classes</a></section>
<?php elseif(!$selectedClass): ?><div class="alert alert-warn">This class is not available to your account. Ask an administrator to assign you as its class teacher.</div>
<?php else: ?>
  <div class="stat-strip attendance-stats"><div><span>Present</span><b><?= $totals['Present'] ?></b></div><div><span>Absent</span><b><?= $totals['Absent'] ?></b></div><div><span>Late / excused</span><b><?= $totals['Late']+$totals['Excused'] ?></b></div><div><span>Unmarked</span><b><?= $unmarked ?></b></div></div>
  <?php if(!$roster): ?><section class="panel empty-state"><h2>No learners enrolled in this class on this date</h2><p>Check the learner’s dated class history and the selected register date.</p></section><?php else: ?>
  <form method="post" action="actions/attendance_save.php" class="panel attendance-register"><?= csrf_field() ?><input type="hidden" name="class_id" value="<?= (int)$selectedClass['id'] ?>"><input type="hidden" name="attendance_date" value="<?= h($attendanceDate) ?>"><div class="panel-heading"><div><h2>Form <?= (int)$selectedClass['form_level'] ?><?= h($selectedClass['stream']) ?> register</h2><p><?= count($roster) ?> learner<?= count($roster)===1?'':'s' ?> enrolled on <?= h(date('l, d F Y',strtotime($attendanceDate))) ?> · Class teacher: <?= h($selectedClass['class_teacher']?:'Unassigned') ?></p></div><button class="primary-button">Save attendance</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Admission no.</th><th>Attendance</th><th>Note / reason</th></tr></thead><tbody><?php foreach($roster as $learner): ?><tr><td><div class="learner-cell"><span class="learner-avatar"><?= h(strtoupper(substr($learner['first_name'],0,1).substr($learner['last_name'],0,1))) ?></span><b><?= h($learner['first_name'].' '.$learner['last_name']) ?></b></div></td><td class="muted-cell"><?= h($learner['admission_no']) ?></td><td><select class="attendance-status" name="attendance[<?= (int)$learner['id'] ?>][status]" required><option value="">Select status</option><?php foreach(['Present','Absent','Late','Excused'] as $status): ?><option <?= $learner['status']===$status?'selected':'' ?>><?= $status ?></option><?php endforeach; ?></select></td><td><input class="attendance-note" name="attendance[<?= (int)$learner['id'] ?>][note]" value="<?= h($learner['note']??'') ?>" maxlength="255" placeholder="Optional note"></td></tr><?php endforeach; ?></tbody></table></div><div class="attendance-actions"><span>Unmarked: <?= $unmarked ?></span><button class="primary-button">Save attendance</button></div></form>
  <?php endif; ?>
<?php endif; ?>
